                    if (logTable != null && logTable.getModel() instanceof javax.swing.table.DefaultTableModel) {
                        javax.swing.table.DefaultTableModel model = (javax.swing.table.DefaultTableModel) logTable.getModel();
                        // Create a row representation; adjust columns as needed
                        Object[] row = new Object[] { lr.getMillis(), lr.getLevel(), lr.getSourceClassName(),
                                                     lr.getSourceMethodName(), lr.getMessage() };
                        model.addRow(row);
                    }
                } catch (Throwable t) {
                    // If UI update fails, log the error but avoid crashing the application
                    java.util.logging.Logger.getLogger(getClass().getName())
                            .log(java.util.logging.Level.SEVERE, "Failed to add log record to table", t);
                }
            }
        });
    } catch (Throwable ex) {
        // Catch potential errors when posting to the event dispatch thread
        java.util.logging.Logger.getLogger(getClass().getName())
                .log(java.util.logging.Level.SEVERE, "SwingUtilities.invokeLater failed", ex);
    }
}

